// 忠实复刻模板表达式逻辑并断言
// If1: from.id === allow(数字比较, equals)
// If : text 为空 → 语音分支
const results = [];
function assert(name, cond, detail) { results.push({ name, pass: !!cond, detail }); if (!cond) throw new Error('断言失败: ' + name + ' ' + JSON.stringify(detail)); }
function if1_allow(fromId, allow) { return Number(fromId) === Number(allow); }
assert('白名单-本人通过', if1_allow(123456789, '123456789'));
assert('白名单-陌生人拦截', !if1_allow(999, '123456789'));
function voiceBranch(text) { return text === undefined || text === null || text === ''; }
assert('分流-纯语音消息走STT', voiceBranch(undefined));
assert('分流-空文本走STT', voiceBranch(''));
assert('分流-有文字走Agent直取', !voiceBranch('今天有什么安排？'));
// 模板已知坑验证：memoryBufferWindow 硬编码 sessionKey=angie_session_default，所有用户共用一份记忆
const memoryNode = { sessionKey: 'angie_session_default', sessionIdType: 'customKey' };
assert('模板memory硬编码sessionKey(已知缺陷已识别)', memoryNode.sessionIdType === 'customKey' && memoryNode.sessionKey === 'angie_session_default');
return [{ json: { u1: 'passed', cases: results.length } }];

const j = $input.first().json;
const out = j.output || j.text || JSON.stringify(j);
const steps = (j.intermediateSteps || []).map(s => ({ tool: s.action && s.action.tool, input: s.action && s.action.toolInput, obs: String(s.observation).slice(0,200) }));
const checks = {
  非空输出: out.length > 10,
  工具调用数3: steps.length === 3,
  计算器结果回传: steps.some(s => s.tool === 'calculator' && s.obs.includes('12193263111263526')),
  日历结果回传: steps.some(s => s.tool === 'google_calendar' && s.obs.includes('weekly-product-sync')),
  任务结果回传: steps.some(s => s.tool === 'task_list' && s.obs.includes('weekly-report')),
  答案融合日历: out.includes('weekly-product-sync') || out.includes('14:00'),
  答案融合任务: out.includes('weekly-report') || out.includes('回复客户邮件')
};
const failed = Object.entries(checks).filter(([k,v]) => !v).map(([k]) => k);
if (failed.length) throw new Error('U2失败: ' + failed.join(',') + ' | 输出=' + out.slice(0,200) + ' | steps=' + JSON.stringify(steps).slice(0,500));
return [{ json: { u2: 'passed', checks: Object.keys(checks).length, outputPreview: out.slice(0, 300), toolSteps: steps } }];
